"use client";

import { useMemo, ReactNode } from "react";

type OrbitShape = "ellipse" | "circle";

interface OrbitLabelsProps {
  items: ReactNode[];
  shape?: OrbitShape;
  baseWidth?: number;
  radiusX?: number;
  radiusY?: number;
  radius?: number;
  duration?: number;
  itemWidth?: number;
  itemHeight?: number;
  direction?: "normal" | "reverse";
  fill?: boolean;
  width?: number | "100%";
  height?: number | "100%";
  className?: string;
  showPath?: boolean;
  pathColor?: string;
  pathWidth?: number;
  paused?: boolean;
  centerContent?: ReactNode;
}

function generateEllipsePath(cx: number, cy: number, rx: number, ry: number): string {
  return `M ${cx - rx} ${cy} A ${rx} ${ry} 0 1 0 ${cx + rx} ${cy} A ${rx} ${ry} 0 1 0 ${cx - rx} ${cy}`;
}

function generateCirclePath(cx: number, cy: number, r: number): string {
  return generateEllipsePath(cx, cy, r, r);
}

export default function OrbitLabels({
  items = [],
  shape = "ellipse",
  baseWidth = 540,
  radiusX = 240,
  radiusY = 180,
  radius = 150,
  duration = 58,
  itemWidth = 160,
  itemHeight = 80,
  direction = "normal",
  fill = true,
  width = "100%",
  height = "100%",
  className = "",
  showPath = false,
  pathColor = "rgba(0,0,0,0.1)",
  pathWidth = 2,
  paused = false,
  centerContent,
}: OrbitLabelsProps) {
  const designCenterX = baseWidth / 2;
  const designCenterY = baseWidth / 2;

  const path = useMemo(() => {
    switch (shape) {
      case "circle":
        return generateCirclePath(designCenterX, designCenterY, radius);
      case "ellipse":
      default:
        return generateEllipsePath(designCenterX, designCenterY, radiusX, radiusY);
    }
  }, [shape, designCenterX, designCenterY, radiusX, radiusY, radius]);

  const keyframes = useMemo(() => `
    @keyframes orbit {
      from { offset-distance: 0%; }
      to { offset-distance: 100%; }
    }
    @keyframes orbitReverse {
      from { offset-distance: 100%; }
      to { offset-distance: 0%; }
    }
  `, []);

  const animationName = direction === "reverse" ? "orbitReverse" : "orbit";

  return (
    <>
      <style jsx global>{keyframes}</style>
      <style jsx global>{`
        .orbit-item {
          animation: ${animationName} ${duration}s linear infinite;
          animation-play-state: ${paused ? 'paused' : 'running'};
        }
      `}</style>
      <div
        className={`relative mx-auto ${className}`}
        style={{ width, height }}
        aria-hidden="true"
      >
        <div
          className="relative w-full h-full"
          style={{ width: baseWidth, height: baseWidth }}
        >
          {showPath && (
            <svg
              width="100%"
              height="100%"
              viewBox={`0 0 ${baseWidth} ${baseWidth}`}
              className="absolute inset-0 pointer-events-none"
            >
              <path
                d={path}
                fill="none"
                stroke={pathColor}
                strokeWidth={pathWidth}
              />
            </svg>
          )}

          {items.map((item, index) => (
            <div
              key={index}
              className="orbit-item absolute will-change-transform select-none pointer-events-auto"
              style={{
                width: itemWidth,
                height: itemHeight,
                offsetPath: `path("${path}")`,
                offsetRotate: "0deg",
                offsetAnchor: "50% 50%",
                offsetDistance: fill ? `${(index / items.length) * 100}%` : '0%',
              }}
            >
              {item}
            </div>
          ))}
        </div>

        {centerContent && (
          <div className="absolute inset-0 flex items-center justify-center z-10">
            {centerContent}
          </div>
        )}
      </div>
    </>
  );
}
